//! Exact raw NOSCRIPT replacement uses actual native Text and staged mutation.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document_with_scripting("<body><noscript id=host>Held</noscript><button id=button><noscript id=guard>Guarded</noscript></button><p id=out>Real</p>",true,&||Ok(())).unwrap();let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://noscript-units.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn refusal(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str)->String{let source=format!("var failure=null;try{{{s}}}catch(e){{failure=e.name+': '+e.message;}}");match p.runtime.execute(&source,&mut Bridge{doc:d,forms:f,state:&mut p.state}){Err(e)=>e,Ok(_)=>{let Value::String(e)=p.runtime.execute("failure",&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap()else{panic!("Expected refusal: {s}")};e}}}
#[test]
fn noscript_inner_html_units_exact_native_records_ranges_clone_clear_and_recovery(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var host=document.getElementById('host'),old=host.firstChild,r=document.createRange(),watch=new MutationObserver(function(){});r.setStart(old,1);r.setEnd(old,3);watch.observe(host,{childList:true,characterData:true,subtree:true});var raw='\udfff\ud800\ud83d\ude42\r\nA\rB\0<img id=fake src=missing>&amp;</noscript>',expected='\udfff\ud800\ud83d\ude42\nA\nB\ufffd<img id=fake src=missing>&amp;</noscript>';var iterator=document.createNodeIterator(host,4);if(iterator.nextNode()!==old)throw 'actual native iterator setup';host.innerHTML=raw;var text=host.firstChild,records=watch.takeRecords();if(iterator.nextNode()!==text)throw 'actual native iterator replacement adjustment';if(text===old||text.nodeType!==3||text.data!==expected||text.data.charCodeAt(0)!==57343||text.data.charCodeAt(1)!==55296||host.textContent!==expected||host.innerHTML!==expected||host.outerHTML!=='<noscript id="host">'+expected+'</noscript>'||text.parentNode!==host||text.ownerDocument!==document||old.parentNode!==null||old.data!=='Held'||r.startContainer!==host||r.startOffset!==0||r.endContainer!==host||r.endOffset!==0||records.length!==1||records[0].target!==host||records[0].removedNodes[0]!==old||records[0].addedNodes[0]!==text||document.getElementById('fake')!==null)throw 'actual exact raw replacement and native records';var clone=host.cloneNode(true);if(clone===host||clone.firstChild===text||clone.firstChild.data!==expected||clone.innerHTML!==expected||watch.takeRecords().length)throw 'independent actual exact raw clone';host.innerHTML='';records=watch.takeRecords();if(host.firstChild!==null||text.parentNode!==null||text.data!==expected||clone.firstChild.data!==expected||records.length!==1||records[0].removedNodes[0]!==text||records[0].addedNodes.length)throw 'actual exact raw retirement';host.innerHTML=raw;records=watch.takeRecords();if(host.firstChild===text||host.firstChild.data!==expected||records.length!==1||records[0].addedNodes[0]!==host.firstChild)throw 'fresh exact raw replacement';
"#);assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn noscript_inner_html_units_author_conversion_and_existing_native_resource_guards(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var host=document.getElementById('host'),guarded=document.getElementById('guard'),out=document.getElementById('out'),calls=0;host.innerHTML={toString:function(){calls++;out.textContent='Converted';return '\udfff\ud800&amp;';}};if(calls!==1||host.firstChild.data!=='\udfff\ud800&amp;'||out.textContent!=='Converted')throw 'single DOMString conversion';var watch=new MutationObserver(function(){});watch.observe(document.body,{childList:true,subtree:true});
"#);p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;
 for source in ["guarded.innerHTML='\\udfff\\ud800<img src=missing>';","out.innerHTML='\\udfff\\ud800<img src=missing>';","document.createElement('script').innerHTML='\\ud800';"]{p.begin_job();assert!(!refusal(&mut d,&mut f,&mut p,source).is_empty());if !source.starts_with("document.createElement"){assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}}
 p.begin_job();run(&mut d,&mut f,&mut p,"if(watch.takeRecords().length||guarded.firstChild.data!=='Guarded'||host.firstChild.data!=='\\udfff\\ud800&amp;'||out.textContent!=='Converted')throw 'no guarded mutation prefix';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn noscript_inner_html_units_quota_refusal_preserves_native_prefix_then_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var host=document.getElementById('host'),old=host.firstChild,watch=new MutationObserver(function(){});watch.observe(host,{childList:true,characterData:true,subtree:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let retained=p.state.retained_limit;let nodes=p.state.node_limit;let strings=p.state.limits.host.string_bytes;
 for mode in 0..5{p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=d.nodes.len(),_=>p.state.limits.host.string_bytes=1};let e=refusal(&mut d,&mut f,&mut p,"host.innerHTML='\\udfff\\ud800<img id=fake src=missing>&amp;';").to_ascii_lowercase();assert!(e.contains("limit")||e.contains("allowance")||e.contains("storage"),"{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=retained;p.state.node_limit=nodes;p.state.limits.host.string_bytes=strings;p.begin_job();run(&mut d,&mut f,&mut p,"if(host.firstChild!==old||old.parentNode!==host||old.data!=='Held'||watch.takeRecords().length||document.getElementById('fake')!==null)throw 'no exact raw mutation prefix';");}
 p.begin_job();run(&mut d,&mut f,&mut p,"host.innerHTML='\\udfff\\ud800&amp;';var records=watch.takeRecords();if(host.firstChild===old||host.firstChild.data!=='\\udfff\\ud800&amp;'||old.parentNode!==null||records.length!==1||records[0].removedNodes[0]!==old||records[0].addedNodes[0]!==host.firstChild)throw 'fresh actual raw replacement recovery';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
